import java.io.*;
import java.net.*;
import java.sql.*;
import java.util.logging.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportId = req.getParameter("id");
        String format = req.getParameter("format");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");

        if (reportId == null || reportId.isEmpty()) {
            resp.sendError(400, "Missing report id");
            return;
        }

        // Validate format parameter
        if (format != null && !format.matches("^(csv|json|xml)$")) {
            resp.sendError(400, "Invalid format");
            return;
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // Build query with date filtering
            StringBuilder query = new StringBuilder();
            query.append("SELECT r.id, r.title, r.created_at, r.payload ");
            query.append("FROM reports r ");
            query.append("WHERE r.department_id = ");
            query.append(reportId);

            if (startDate != null && !startDate.isEmpty()) {
                query.append(" AND r.created_at >= '").append(startDate).append("'");
            }
            if (endDate != null && !endDate.isEmpty()) {
                query.append(" AND r.created_at <= '").append(endDate).append("'");
            }

            query.append(" ORDER BY r.created_at DESC LIMIT 100");

            log.info("Executing report query for dept: " + reportId);

            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(query.toString());

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                first = false;
                out.printf("  {\"id\": %d, \"title\": \"%s\", \"created\": \"%s\"}",
                    rs.getInt("id"),
                    rs.getString("title").replace("\"", "\\\""),
                    rs.getTimestamp("created_at").toString());
            }
            out.print("\n]");
            out.flush();
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Database error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Batch delete - also vulnerable but requires auth token
        String authHeader = req.getHeader("X-Internal-Token");
        if (authHeader == null || !authHeader.equals(System.getenv("INTERNAL_TOKEN"))) {
            resp.sendError(403, "Forbidden");
            return;
        }
        String ids = req.getParameter("ids");
        if (ids == null) {
            resp.sendError(400, "Missing ids");
            return;
        }
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            String deleteQuery = "DELETE FROM reports WHERE id IN (" + ids + ")";
            Statement stmt = conn.createStatement();
            int affected = stmt.executeUpdate(deleteQuery);
            resp.getWriter().print("{\"deleted\": " + affected + "}");
        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }
}
